import piexif from 'piexifjs';
import sharp from 'sharp';

/**
 * Deterministic, in-repo image fixtures for the upload pipeline.
 *
 * Nothing depends on an external file; every bitmap is generated by `sharp`
 * and the EXIF/GPS fixture is filled by `piexifjs`.
 */

export interface ImageFixture {
  readonly buffer: Buffer;
  readonly contentType: string;
  readonly filename: string;
}

function createBase(width = 120, height = 80) {
  return sharp({
    create: {
      width,
      height,
      channels: 3,
      background: { r: 32, g: 96, b: 160 },
    },
  });
}

export async function createJpeg(width = 120, height = 80): Promise<Buffer> {
  return createBase(width, height).jpeg({ quality: 90 }).toBuffer();
}

export async function createPng(width = 120, height = 80): Promise<Buffer> {
  return createBase(width, height).png().toBuffer();
}

export async function createWebp(width = 120, height = 80): Promise<Buffer> {
  return createBase(width, height).webp({ quality: 90 }).toBuffer();
}

export function createSvg(): Buffer {
  return Buffer.from(
    '<svg xmlns="http://www.w3.org/2000/svg" width="120" height="80">' +
      '<rect width="120" height="80" fill="#2060a0" />' +
      '</svg>',
    'utf8',
  );
}

/** 1×1 transparent GIF, the smallest reliable fixture. */
export function createGif(): Buffer {
  return Buffer.from('R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7', 'base64');
}

/** Minimal ISO BMFF header declaring the HEIC brand; file-type detects it. */
export function createHeic(): Buffer {
  return Buffer.from('0000001466747970686569630000000068656963', 'hex');
}

/** Minimal ISO BMFF header declaring the AVIF brand; file-type detects it. */
export function createAvif(): Buffer {
  return Buffer.from('0000001466747970617669660000000061766966', 'hex');
}

/**
 * Rewrites the SOF dimensions of a JPEG in place.
 *
 * The scan data is untouched, but sharp rejects oversized inputs as soon as it
 * reads the header, before decoding, so this exercises the 50 MP limit without
 * allocating a real 60 MP image.
 */
export function patchJpegDimensions(jpeg: Buffer, width: number, height: number): Buffer {
  const patched = Buffer.from(jpeg);
  let offset = 2;

  while (offset + 9 < patched.length) {
    if (patched[offset] !== 0xff) {
      throw new Error('Invalid JPEG segment marker');
    }

    const marker = patched[offset + 1];

    if (marker === undefined) {
      break;
    }

    if (marker === 0xd8 || marker === 0x01 || (marker >= 0xd0 && marker <= 0xd7)) {
      offset += 2;
      continue;
    }

    if (marker === 0xda) {
      break;
    }

    const segmentLength = patched.readUInt16BE(offset + 2);
    const isStartOfFrame =
      marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc;

    if (isStartOfFrame) {
      patched.writeUInt16BE(height, offset + 5);
      patched.writeUInt16BE(width, offset + 7);
      return patched;
    }

    offset += 2 + segmentLength;
  }

  throw new Error('JPEG SOF marker not found');
}

/**
 * JPEG with EXIF orientation 6. The stored bitmap is 120×80, so a correct
 * pipeline produces a 80×120 original and variants.
 */
export async function createOrientedJpeg(): Promise<Buffer> {
  return createBase(120, 80).withMetadata({ orientation: 6 }).jpeg({ quality: 90 }).toBuffer();
}

function toDms(value: number): [[number, number], [number, number], [number, number]] {
  const degrees = Math.floor(value);
  const minutesFloat = (value - degrees) * 60;
  const minutes = Math.floor(minutesFloat);
  const seconds = Math.round((minutesFloat - minutes) * 60 * 10_000);

  return [
    [degrees, 1],
    [minutes, 1],
    [seconds, 10_000],
  ];
}

/**
 * JPEG with `DateTimeOriginal` and GPS coordinates (Palma: 39.5696, 2.6502).
 * Coordinates must leave the pipeline only as a geocoded `placeName`.
 */
export async function createGpsJpeg(): Promise<Buffer> {
  const jpeg = await createJpeg();
  const exif = piexif.dump({
    '0th': {},
    Exif: {
      [piexif.ExifIFD.DateTimeOriginal]: '2024:05:06 07:08:09',
    },
    GPS: {
      [piexif.GPSIFD.GPSLatitudeRef]: 'N',
      [piexif.GPSIFD.GPSLatitude]: toDms(39.5696),
      [piexif.GPSIFD.GPSLongitudeRef]: 'E',
      [piexif.GPSIFD.GPSLongitude]: toDms(2.6502),
    },
    '1st': {},
    thumbnail: null,
  });

  return Buffer.from(piexif.insert(exif, jpeg.toString('binary')), 'binary');
}

/**
 * A JPEG whose magic bytes survive but whose body is truncated, so `file-type`
 * recognises JPEG and `sharp` cannot decode it (`INVALID_IMAGE`).
 */
export async function createCorruptJpeg(): Promise<Buffer> {
  const jpeg = await createJpeg();

  return jpeg.subarray(0, Math.min(64, jpeg.length));
}
